-- PART 4: MESSAGE READS (read receipts)

INSERT INTO public.message_reads (message_id, user_id, channel_id, read_at)
SELECT
  m.id,
  u.id,
  m.channel_id,
  m.created_at + INTERVAL '5 minutes' + (random() * INTERVAL '2 hours')
FROM public.messages m
CROSS JOIN public.users u
WHERE m.channel_id IN ('c0000001-0000-4000-8000-000000000001', 'c0000002-0000-4000-8000-000000000002', 'c0000003-0000-4000-8000-000000000003')
  AND m.created_at > '2026-04-01'
  AND u.id IN (
    'a0000001-0000-4000-8000-000000000001',
    'a0000003-0000-4000-8000-000000000003',
    'a0000004-0000-4000-8000-000000000004',
    'a0000005-0000-4000-8000-000000000005',
    'a0000011-0000-4000-8000-000000000011',
    'a0000017-0000-4000-8000-000000000017'
  )
  AND EXISTS (
    SELECT 1 FROM public.channel_members cm
    WHERE cm.channel_id = m.channel_id AND cm.user_id = u.id
  )
LIMIT 150
ON CONFLICT (message_id, user_id) DO NOTHING;

